fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Compute S(k) = sum_{i=1}^k a[i], where
    // a[i] = -i if i is odd, +i if i is even.
    // Closed‐form:
    //   S(k) = 0                 if k <= 0
    //   S(k) =  k/2             if k is even
    //   S(k) = -(k+1)/2         if k is odd
    fn prefix_sum(k: i32) -> i32 {
        if k <= 0 {
            0
        } else if k % 2 == 0 {
            k / 2
        } else {
            -((k + 1) / 2)
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| {
            let sum_r = prefix_sum(r as i32);
            let sum_lm1 = prefix_sum((l - 1) as i32);
            // The query sum is S(r) - S(l-1).
            (sum_r - sum_lm1) as i8
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn basic() {
        let queries = vec![(1, 1), (1, 2), (2, 3), (3, 6), (5, 5)];
        // a = [-1, +2, -3, +4, -5, +6, ...]
        // sums: [ -1,
        //         -1+2 = 1,
        //          2-3 = -1,
        //        -3+4-5+6 = 2,
        //           -5 ]
        let expected = vec![-1, 1, -1, 2, -5];
        assert_eq!(solve(queries), expected);
    }

    #[test]
    fn larger_ranges() {
        // Check some random ranges against a direct compute.
        let mut qs = Vec::new();
        let mut want = Vec::new();
        for l in 1..=10 {
            for r in l..=10 {
                qs.push((l, r));
                let mut s = 0;
                for i in l..=r {
                    s += if i % 2 == 0 { i } else { -i };
                }
                want.push(s as i8);
            }
        }
        assert_eq!(solve(qs), want);
    }
}